export function getTenancyForTable(name: string): TenancyModel {
  return TENANCY_BOUNDARY_MAP[name]?.model ?? "user_id";
}

export function getTenancyEntry(name: string): TenancyBoundaryEntry | undefined {
  return TENANCY_BOUNDARY_MAP[name];
}

export function getGlobalTables(): string[] {
  return Object.entries(TENANCY_BOUNDARY_MAP)
    .filter(([, e]) => e.model === "global")
    .map(([name]) => name);
}

export function getTablesByTenancy(model: TenancyModel): string[] {
  return Object.entries(TENANCY_BOUNDARY_MAP)
    .filter(([, e]) => e.model === model)
    .map(([name]) => name);
}

